-- create-table /TRDEMOOTTO/OTTO_SHOPS
CREATE TABLE "/TRDEMOOTTO/OTTO_SHOPS" (
  "/RT/TENANT" TEXT NOT NULL,
  "SHOP_ID" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#PK" PRIMARY KEY ("/RT/TENANT", "SHOP_ID"),
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#FK#CONNECTION" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "/TRDEMOOTTO/OTTO_CONNECTIONS" ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#CK#SHOP_ID" CHECK ("SHOP_ID" IS NULL OR (length("SHOP_ID") <= 12)),
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "/TRDEMOOTTO/OTTO_SHOPS#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80))
) STRICT;

